diff --git a/src/execution/reactor.c b/src/execution/reactor.c
index 9c48428..6e80a95 100644
--- a/src/execution/reactor.c
+++ b/src/execution/reactor.c
@@ -20,6 +20,8 @@
 #include <assert.h>
 #include <errno.h>
 #include <limits.h>
+#include <inttypes.h>
+#include <stdio.h>
 #include <pthread.h>
 #include <stdatomic.h>
 #include <stddef.h>
@@ -58,6 +60,7 @@ _Static_assert(
  * 外部线程不会写该 TLS，因此所有者校验不需要互斥锁或原子操作。
  */
 static _Thread_local struct tr_reactor *tr_current_reactor_owner;
+static _Thread_local unsigned tr_control_probe_phase;

 static int tr_reactor_is_owner_thread(const struct tr_reactor *reactor)
 {
@@ -111,7 +114,21 @@ struct tr_tx_item {
 	uint64_t wire_len;
 };

+struct tr_tx_probe_sample {
+	unsigned phase;
+	uint16_t type;
+	uint32_t slot;
+	uint32_t command_count;
+	uint32_t ready_connections;
+	uint32_t waiting_connections;
+	uint32_t queued_control[32];
+	uint32_t queued_data;
+};
+
 struct tr_tx_pool {
+	uint64_t probe_acquired[32][7];
+	uint64_t probe_failed[32][7];
+	uint64_t probe_released[32];
 	pthread_mutex_t lock;
 	struct tr_tx_item *items;
 	struct tr_tx_item *free_list;
@@ -307,6 +324,9 @@ struct tr_reactor {
 	struct tr_timer_queue timers;
 	struct tr_tx_pool tx_pool;
 	struct tr_tx_pool control_tx_pool;
+	struct tr_tx_probe_sample probe_samples[8];
+	unsigned probe_sample_count;
+	unsigned char probe_sample_seen[32][7];
 	struct tr_buffer_pool rx_pool;

 	struct tr_slot *slots;
@@ -462,6 +482,60 @@ static void tr_conn_token_decode(uint64_t token, uint32_t *slot,
 	*generation = (uint32_t)(token >> 32);
 }

+static void tr_tx_probe_sample(struct tr_reactor *reactor,
+                               uint16_t type, uint32_t slot)
+{
+	struct tr_tx_probe_sample *sample;
+	if (!tr_reactor_is_owner_thread(reactor) ||
+	    reactor->probe_sample_count == 8U ||
+	    reactor->probe_sample_seen[type][tr_control_probe_phase])
+		return;
+	reactor->probe_sample_seen[type][tr_control_probe_phase] = 1U;
+	sample = &reactor->probe_samples[reactor->probe_sample_count++];
+	sample->phase = tr_control_probe_phase;
+	sample->type = type;
+	sample->slot = slot;
+	pthread_mutex_lock(&reactor->commands.lock);
+	sample->command_count = reactor->commands.count;
+	pthread_mutex_unlock(&reactor->commands.lock);
+	for (struct tr_connection *connection = reactor->tx_ready_head;
+	     connection; connection = connection->tx_ready_next)
+		sample->ready_connections++;
+	for (uint32_t i = 0U; i < reactor->config.max_connections; ++i) {
+		struct tr_connection *connection = &reactor->connections[i];
+		if (connection->state != TR_CONN_ACTIVE)
+			continue;
+		if (connection->tx_wait_writable ||
+		    (connection->byte_endpoint &&
+		     connection->byte_endpoint->write_wait))
+			sample->waiting_connections++;
+		for (struct tr_tx_item *item = connection->tx_head;
+		     item; item = item->next) {
+			if (item->owner_pool == &reactor->control_tx_pool)
+				sample->queued_control[item->type]++;
+			else if (item->owner_pool == &reactor->tx_pool)
+				sample->queued_data++;
+		}
+	}
+}
+
+static void tr_tx_probe_report(struct tr_reactor *reactor)
+{
+	for (unsigned i = 0; i < reactor->probe_sample_count; ++i) {
+		struct tr_tx_probe_sample *s = &reactor->probe_samples[i];
+		fprintf(stderr, "{\"type\":\"control_tx_probe_sample\","
+		        "\"phase\":%u,\"frame_type\":%u,\"slot\":%u,"
+		        "\"command_count\":%u,\"ready_connections\":%u,"
+		        "\"waiting_connections\":%u,\"queued_data\":%u,"
+		        "\"queued_control\":[", s->phase, s->type, s->slot,
+		        s->command_count, s->ready_connections,
+		        s->waiting_connections, s->queued_data);
+		for (unsigned j = 0; j < 32U; ++j)
+			fprintf(stderr, "%s%u", j ? "," : "", s->queued_control[j]);
+		fprintf(stderr, "]}\n");
+	}
+}
+
 static int tr_tx_pool_init(struct tr_tx_pool *pool, uint32_t capacity)
 {
 	struct tr_tx_item *items TR_AUTO(tr_tx_item_array_cleanup) = NULL;
@@ -495,6 +569,22 @@ static void tr_tx_pool_destroy(struct tr_tx_pool *pool)
 	if (!pool)
 		return;

+	for (unsigned type = 1U; type < 32U; ++type) {
+		for (unsigned phase = 0U; phase < 7U; ++phase) {
+			if (!pool->probe_acquired[type][phase] &&
+			    !pool->probe_failed[type][phase])
+				continue;
+			fprintf(stderr, "{\"type\":\"tx_pool_probe\","
+			        "\"capacity\":%u,\"free_final\":%u,"
+			        "\"frame_type\":%u,\"phase\":%u,"
+			        "\"acquired\":%" PRIu64 ",\"failed\":%" PRIu64
+			        ",\"released_type_total\":%" PRIu64 "}\n",
+			        pool->capacity, pool->free_count, type, phase,
+			        pool->probe_acquired[type][phase],
+			        pool->probe_failed[type][phase],
+			        pool->probe_released[type]);
+		}
+	}
 	free(pool->items);
 	pool->items = NULL;
 	pool->free_list = NULL;
@@ -505,7 +595,7 @@ static void tr_tx_pool_destroy(struct tr_tx_pool *pool)
 	pthread_mutex_destroy(&pool->lock);
 }

-static struct tr_tx_item *tr_tx_pool_acquire(struct tr_tx_pool *pool)
+static struct tr_tx_item *tr_tx_pool_acquire(struct tr_tx_pool *pool, uint16_t type)
 {
 	struct tr_tx_item *item;

@@ -514,10 +604,12 @@ static struct tr_tx_item *tr_tx_pool_acquire(struct tr_tx_pool *pool)
 	if (item) {
 		pool->free_list = item->next;
 		pool->free_count--;
+		pool->probe_acquired[type][tr_control_probe_phase]++;
 		tr_observe_high_water_u32(&pool->peak_in_use,
 					  pool->capacity - pool->free_count);
 	} else {
 		pool->exhausted_events++;
+		pool->probe_failed[type][tr_control_probe_phase]++;
 	}
 	pthread_mutex_unlock(&pool->lock);

@@ -544,6 +636,7 @@ static void tr_tx_pool_release(struct tr_tx_pool *pool, struct tr_tx_item *item)
 	item->wire_len = 0;

 	pthread_mutex_lock(&pool->lock);
+	pool->probe_released[item->type]++;
 	item->next = pool->free_list;
 	pool->free_list = item;
 	if (pool->free_count == 0)
@@ -3645,6 +3738,7 @@ static void *tr_reactor_thread_main(void *arg)
 		int count;
 		int i;

+		tr_control_probe_phase = 1U;
 		commands_pending = tr_process_commands(reactor, &turn);
 		if (reactor->stopping) {
 			tr_record_turn(reactor, &turn);
@@ -3652,12 +3746,18 @@ static void *tr_reactor_thread_main(void *arg)
 			break;
 		}

+		tr_control_probe_phase = 2U;
 		completions_pending = tr_process_completions(reactor,
 							     &turn.left.completions);
+		tr_control_probe_phase = 3U;
 		timers_pending = tr_process_timers(reactor, &turn);
+		tr_control_probe_phase = 4U;
 		tr_run_tx_capacity_ready(reactor, &turn);
+		tr_control_probe_phase = 5U;
 		tr_run_rx_ready(reactor, &turn);
+		tr_control_probe_phase = 6U;
 		tr_run_tx_ready(reactor, &turn);
+		tr_control_probe_phase = 4U;
 		tr_run_tx_capacity_ready(reactor, &turn);
 		tr_reactor_flush_tx_drained(reactor);

@@ -3669,6 +3769,7 @@ static void *tr_reactor_thread_main(void *arg)
 		else
 			turn.poll_timeout = tr_reactor_timer_timeout_ms(reactor);

+		tr_control_probe_phase = 0U;
 		turn.polled = 1;
 		if (reactor->config.observability_flags & TR_OBSERVABILITY_TIMING)
 			turn.poll_start_ns = tr_reactor_now_ns();
@@ -3688,8 +3789,10 @@ static void *tr_reactor_thread_main(void *arg)
 		}

 		for (i = 0; i < count; ++i) {
+			tr_control_probe_phase = 0U;
 			if (events[i].data.u64 == TR_WAKE_TOKEN) {
 				tr_reactor_drain_wake(reactor);
+				tr_control_probe_phase = 2U;
 				(void)tr_process_completions(reactor,
 							     &turn.left.completions);
 			} else if (events[i].data.u64 == TR_LISTENER_TOKEN) {
@@ -3717,10 +3820,14 @@ static void *tr_reactor_thread_main(void *arg)
 			}
 		}

+		tr_control_probe_phase = 5U;
 		tr_run_rx_ready(reactor, &turn);
 		/* I/O 可能越过截止时间，但不会补充定时器或发送预算。 */
+		tr_control_probe_phase = 3U;
 		(void)tr_process_timers(reactor, &turn);
+		tr_control_probe_phase = 6U;
 		tr_run_tx_ready(reactor, &turn);
+		tr_control_probe_phase = 4U;
 		tr_run_tx_capacity_ready(reactor, &turn);
 		tr_reactor_flush_tx_drained(reactor);
 		tr_record_turn(reactor, &turn);
@@ -5293,8 +5400,10 @@ static int tr_reactor_sendv_internal(struct tr_conn_handle connection,

 	item = tr_tx_pool_acquire(type == TR_FRAME_DATA ?
 					  &reactor->tx_pool :
-					  &reactor->control_tx_pool);
+					  &reactor->control_tx_pool, type);
 	if (!item) {
+		if (type != TR_FRAME_DATA)
+			tr_tx_probe_sample(reactor, type, connection.slot);
 		if (pool_exhausted)
 			*pool_exhausted = type == TR_FRAME_DATA;
 		return TR_AGAIN;
@@ -6382,6 +6491,7 @@ int tr_reactor_destroy(struct tr_reactor *reactor)
 	}

 	tr_tx_pool_destroy(&reactor->control_tx_pool);
+	tr_tx_probe_report(reactor);
 	tr_tx_pool_destroy(&reactor->tx_pool);
 	tr_timer_queue_destroy(&reactor->timers);
 	tr_completion_queue_destroy(&reactor->completions);

